('coc1_m1', 'css-sag-20261009-v1', '{"id":"coc1_m1","cocId":"coc1","title":"Identify Computer Parts and Tools","scenario":"Inspect a de-energized desktop before servicing. The memory latch is open. Identify component roles, isolate abnormalities, and record a safe work plan.","environmentLabel":"Hardware inspection bench","practiceGuidance":"Inspect labels and visible conditions before recording any decision.","scene":{"id":"coc1_m1_scene","backgroundAsset":"assets/images/COC1.png","objects":[{"id":"motherboard","label":"Motherboard","x":0.08,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["motherboard_port"],"initialState":"neutral","metadata":{"schematicRole":"primary","description":"Motherboard","replaceableAsset":"assets/simulation/schematics/motherboard.svg","imageAsset":"assets/COC1/Mission 1/motherboard.png"}},{"id":"cpu","label":"Processor","x":0.38,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["cpu_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Processor","replaceableAsset":"assets/simulation/schematics/cpu.svg","imageAsset":"assets/COC1/Mission 1/cpu.png"}},{"id":"ram","label":"Memory module","x":0.6799999999999999,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["ram_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Memory module","replaceableAsset":"assets/simulation/schematics/ram.svg","imageAsset":"assets/COC1/Mission 1/ram.png"}},{"id":"psu","label":"Power supply","x":0.08,"y":0.44000000000000006,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["psu_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Power supply","replaceableAsset":"assets/simulation/schematics/psu.svg","imageAsset":"assets/COC1/Mission 1/psu.png"}},{"id":"cpu_socket","label":"CPU socket","x":0.38,"y":0.44000000000000006,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["cpu_socket_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"CPU socket","replaceableAsset":"assets/simulation/schematics/cpu_socket.svg","imageAsset":null}},{"id":"dimm_slot","label":"DIMM slot","x":0.6799999999999999,"y":0.44000000000000006,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["dimm_slot_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"DIMM slot","replaceableAsset":"assets/simulation/schematics/dimm_slot.svg","imageAsset":null}},{"id":"atx_power_port","label":"24-pin ATX power header","x":0.08,"y":0.78,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["atx_power_port_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"24-pin ATX power header","replaceableAsset":"assets/simulation/schematics/atx_power_port.svg","imageAsset":null}},{"id":"anti_static_strap","label":"Anti-static wrist strap","x":0.38,"y":0.78,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["anti_static_strap_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Anti-static wrist strap","replaceableAsset":"assets/simulation/schematics/anti_static_strap.svg","imageAsset":"assets/COC1/Mission 1/anti_static_wrist_strap.png"}}],"initialStatus":{"schematic":true,"replaceableAssets":true,"statusLabel":"Awaiting inspection","sceneKind":"workbench"}},"phases":[{"id":"coc1_m1_p1","title":"Inspect hardware","instruction":"Inspect each component and its visible condition.","primaryInteraction":"inspect","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"feedbackIds":["coc1_m1_constraint"],"presentation":{"component":"tap_inspect","objects":[{"id":"motherboard","label":"Motherboard","inspection":"ATX board. CPU socket, keyed DIMM slots, and 24-pin power header are visible. No swollen capacitors are visible.","description":"Motherboard","imageAsset":"assets/COC1/Mission 1/motherboard.png"},{"id":"cpu","label":"Processor","inspection":"Processor contacts are intact. The alignment mark must match the socket mark; do not force the package.","description":"Processor","imageAsset":"assets/COC1/Mission 1/cpu.png"},{"id":"ram","label":"Memory module","inspection":"DDR memory module. The notch is offset; one retaining latch is open. Isolate power before reseating.","description":"Memory module","imageAsset":"assets/COC1/Mission 1/ram.png"},{"id":"psu","label":"Power supply","inspection":"Power supply converts mains to regulated DC rails. Disconnect mains before touching internal connectors.","description":"Power supply","imageAsset":"assets/COC1/Mission 1/psu.png"},{"id":"cpu_socket","label":"CPU socket","inspection":"The keyed CPU socket is empty and its alignment marker is visible. No contacts appear bent.","description":"CPU socket","imageAsset":null},{"id":"dimm_slot","label":"DIMM slot","inspection":"The DIMM slot key and retaining latches are visible; one latch remains open.","description":"DIMM slot","imageAsset":null},{"id":"atx_power_port","label":"24-pin ATX power header","inspection":"The 24-pin ATX header is keyed and clear of debris. It must remain de-energized during inspection.","description":"24-pin ATX power header","imageAsset":null}],"equipment":{"single_connection":true},"mechanics":["inspect_hardware"]}},{"id":"coc1_m1_p2","title":"Select a safe set","instruction":"Record the components and safety equipment needed for the work.","primaryInteraction":"select","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"feedbackIds":["coc1_m1_constraint"],"presentation":{"component":"multi_select","options":[{"id":"esd_protection","label":"Wrist strap — ESD protection"},{"id":"open_memory_latch","label":"Memory latch requires attention"},{"id":"service_live","label":"Service while energized"}],"equipment":{"single_connection":true,"selection_groups":[{"id":"processing","label":"Classify: processing","options":[{"id":"cpu","label":"Processor"},{"id":"ram","label":"Memory module"},{"id":"psu","label":"Power supply"}]},{"id":"memory","label":"Classify: volatile memory","options":[{"id":"cpu","label":"Processor"},{"id":"ram","label":"Memory module"},{"id":"psu","label":"Power supply"}]},{"id":"power","label":"Classify: power conversion","options":[{"id":"cpu","label":"Processor"},{"id":"ram","label":"Memory module"},{"id":"psu","label":"Power supply"}]}],"tools":[{"id":"anti_static_strap","label":"Anti-static wrist strap","compatible_categories":["esd_ground"]},{"id":"screwdriver","label":"Phillips screwdriver","compatible_categories":["fastener"]}],"targets":[{"id":"chassis_ground","label":"Bare chassis ground point","category":"esd_ground"},{"id":"case_fastener","label":"Case fastener","category":"fastener"}],"completion":[{"path":"selection.coc1_m1_p2","operator":"present"},{"path":"classification.processing","operator":"present"},{"path":"classification.memory","operator":"present"},{"path":"classification.power","operator":"present"},{"path":"tool.chassis_ground","value":"anti_static_strap"},{"path":"tool.case_fastener","value":"screwdriver"}]},"mechanics":["select_safe_set"]}},{"id":"coc1_m1_p3","title":"Record observations","instruction":"Describe the inspected condition without inferring an unobserved fault.","primaryInteraction":"observe","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"feedbackIds":["coc1_m1_constraint"],"presentation":{"component":"observation","equipment":{"single_connection":true},"mechanics":["record_observation"]}},{"id":"coc1_m1_p4","title":"Verify readiness","instruction":"Run the readiness check against the recorded inspection.","primaryInteraction":"testRun","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"feedbackIds":["coc1_m1_evidence"],"presentation":{"evidenceActionType":"hardware_readiness_test","target":"coc1_m1_test_4","equipment":{"single_connection":true,"checks":[{"id":"inspection","label":"Inspection record","requires":[{"path":"inspected.motherboard","value":true},{"path":"inspected.cpu","value":true},{"path":"inspected.ram","value":true},{"path":"inspected.psu","value":true},{"path":"inspected.cpu_socket","value":true},{"path":"inspected.dimm_slot","value":true},{"path":"inspected.atx_power_port","value":true}],"nominal":"Components, sockets, slots, and the ATX power header were inspected.","fault":"A component, socket, slot, or power-header inspection remains incomplete."},{"id":"classification","label":"Component roles","requires":[{"path":"classification.processing","operator":"set_equals","value":["cpu"]},{"path":"classification.memory","operator":"set_equals","value":["ram"]},{"path":"classification.power","operator":"set_equals","value":["psu"]}],"nominal":"Processing, volatile memory, and power-conversion components classified.","fault":"At least one component role conflicts with the inspected specification."},{"id":"safe_work","label":"Safe work plan","requires":[{"path":"selection.coc1_m1_p2","operator":"set_equals","value":["esd_protection","open_memory_latch"]}],"nominal":"ESD controls and the unseated memory latch are recorded.","fault":"The work plan omits an observed hazard or permits energized servicing."},{"id":"notes","label":"Observation record","requires":[{"path":"observation.coc1_m1_p3","operator":"present"}],"nominal":"Inspection notes attached.","fault":"No inspection notes recorded."},{"id":"close_out","label":"Safety and documentation","requires":[{"path":"setting.work_area_safe","value":true},{"path":"setting.service_report_ready","value":true}],"nominal":"Work-area safety, contingency where required, and service handover recorded.","fault":"Complete safety close-out and the service report before final verification."}],"completion":[{"path":"result.coc1_m1_test_4","value":true}],"operations":[{"id":"close_work_area","label":"Record 5S and 3Rs work-area close-out","effects":{"work_area_safe":true},"requires":[]},{"id":"prepare_service_report","label":"Prepare the technical work report for handover","effects":{"service_report_ready":true},"requires":[{"path":"setting.work_area_safe","value":true}]}]},"mechanics":["verify_readiness"]}},{"id":"coc1_m1_p5","title":"Review evidence","instruction":"Review the safe-set decision and readiness evidence.","primaryInteraction":"review","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","psu","cpu_socket","dimm_slot","atx_power_port","anti_static_strap"],"feedbackIds":["coc1_m1_review"],"presentation":{"equipment":{"single_connection":true},"mechanics":["review_evidence"]}}],"interactionFamilies":["inspect","select","observe","testRun"],"feedbackCatalog":{"coc1_m1_constraint":"Inspect the component label and safety condition before recording the set.","coc1_m1_evidence":"Readiness verification records the observed hardware state.","coc1_m1_review":"Review the inspection, safety selection, and observation evidence before submission."},"reviewMetadata":{"title":"Evidence review","returnLabel":"Return to mission","confirmLabel":"Confirm evidence"}}'::jsonb),
('coc1_m2', 'css-sag-20261009-v1', '{"id":"coc1_m2","cocId":"coc1","title":"Install Internal Components","scenario":"Assemble a compatible workstation from inspected parts.","environmentLabel":"Component assembly bench","practiceGuidance":"Check compatibility and orientation before each controlled placement.","scene":{"id":"coc1_m2_scene","backgroundAsset":"assets/images/COC1.png","objects":[{"id":"motherboard","label":"Motherboard","x":0.04,"y":0.08,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["motherboard_port"],"initialState":"neutral","metadata":{"schematicRole":"primary","description":"Motherboard","replaceableAsset":"assets/simulation/schematics/motherboard.svg","imageAsset":"assets/COC1/Mission 2/motherboard.png"}},{"id":"cpu","label":"Processor","x":0.27999999999999997,"y":0.08,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["cpu_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Processor","replaceableAsset":"assets/simulation/schematics/cpu.svg","imageAsset":"assets/COC1/Mission 2/cpu.png"}},{"id":"ram","label":"Memory module","x":0.52,"y":0.08,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["ram_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Memory module","replaceableAsset":"assets/simulation/schematics/ram.svg","imageAsset":"assets/COC1/Mission 2/ram.png"}},{"id":"storage","label":"Storage drive","x":0.76,"y":0.08,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["storage_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Storage drive","replaceableAsset":"assets/simulation/schematics/storage.svg","imageAsset":"assets/COC1/Mission 2/ssd.png"}},{"id":"cooling_fan","label":"Cooling assembly","x":0.04,"y":0.39,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["cooling_fan_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Cooling assembly","replaceableAsset":"assets/simulation/schematics/cooling_fan.svg","imageAsset":"assets/COC1/Mission 2/cooling_fan.png"}},{"id":"psu","label":"Power supply","x":0.27999999999999997,"y":0.39,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["psu_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Power supply","replaceableAsset":"assets/simulation/schematics/psu.svg","imageAsset":"assets/COC1/Mission 2/psu.png"}},{"id":"atx","label":"24-pin ATX power","x":0.52,"y":0.39,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["atx_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"24-pin ATX power","replaceableAsset":"assets/simulation/schematics/atx.svg","imageAsset":null}},{"id":"sata","label":"SATA data cable","x":0.76,"y":0.39,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["sata_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"SATA data cable","replaceableAsset":"assets/simulation/schematics/sata.svg","imageAsset":null}},{"id":"board_power","label":"Motherboard power header","x":0.04,"y":0.7,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["board_power_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Motherboard power header","replaceableAsset":"assets/simulation/schematics/board_power.svg","imageAsset":null}},{"id":"storage_data","label":"Storage data port","x":0.27999999999999997,"y":0.7,"width":0.2,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["storage_data_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Storage data port","replaceableAsset":"assets/simulation/schematics/storage_data.svg","imageAsset":null}}],"initialStatus":{"sc