ion":"CPU socket","imageAsset":null},{"id":"ram_slot","label":"RAM slot","socket_categories":["slotted"],"description":"RAM slot","imageAsset":null},{"id":"drive_bay","label":"Drive bay","socket_categories":["drive"],"description":"Drive bay","imageAsset":null},{"id":"fan_area","label":"Cooling area","socket_categories":["cooling"],"description":"Cooling area","imageAsset":null},{"id":"psu_bay","label":"Power-supply bay","socket_categories":["power"],"description":"Power-supply bay","imageAsset":null}],"orientations":["aligned","rotated"],"equipment":{"single_connection":true},"mechanics":["place_with_orientation"]}},{"id":"coc1_m2_p3","title":"Sequence assembly","instruction":"Record the installation chronology before final inspection.","primaryInteraction":"sequence","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","storage","cooling_fan","psu"],"feedbackIds":["coc1_m2_constraint"],"presentation":{"component":"sequencing","items":[{"id":"power","label":"Connect power and storage data","description":"Connect power and storage data","imageAsset":null},{"id":"cooling","label":"Secure cooling and memory","description":"Secure cooling and memory","imageAsset":null},{"id":"board","label":"Fit board and processor","description":"Fit board and processor","imageAsset":null},{"id":"isolate","label":"Isolate power and prepare ESD controls","description":"Isolate power and prepare ESD controls","imageAsset":null}],"equipment":{"single_connection":true,"precedence":[{"before":"isolate","after":"board"},{"before":"board","after":"cooling"},{"before":"cooling","after":"power"}],"connection":{"sources":[{"id":"atx","label":"24-pin ATX power","interfaces":["atx"]},{"id":"sata","label":"SATA data cable","interfaces":["sata"]}],"destinations":[{"id":"board_power","label":"Motherboard power header","interface":"atx"},{"id":"storage_data","label":"Storage data port","interface":"sata"}]},"completion":[{"path":"link.atx>board_power","value":true},{"path":"link.sata>storage_data","value":true}]},"mechanics":["sequence_assembly"]}},{"id":"coc1_m2_p4","title":"Verify installation","instruction":"Run seating, fastening, and clearance checks.","primaryInteraction":"testRun","supportingInteractions":[],"availableObjectIds":["motherboard","cpu","ram","storage","cooling_fan","psu"],"feedbackIds":["coc1_m2_evidence"],"presentation":{"evidenceActionType":"installation_test_requested","target":"coc1_m2_test_4","equipment":{"single_connection":true,"checks":[{"id":"assembly","label":"POST component inventory","requires":[{"path":"placed.motherboard","operator":"present"},{"path":"placed.cpu","operator":"present"},{"path":"placed.ram","operator":"present"},{"path":"placed.storage","operator":"present"},{"path":"placed.cooling_fan","operator":"present"},{"path":"placed.psu","operator":"present"}],"nominal":"CPU, memory, storage, cooling, and power assemblies seated.","fault":"An installed component is missing from the inventory."},{"id":"power_data","label":"Power and storage path","requires":[{"path":"link.atx>board_power","value":true},{"path":"link.sata>storage_data","value":true}],"nominal":"Power rails and storage data path available.","fault":"Power or storage connection is incomplete."},{"id":"sequence","label":"Assembly safety record","requires":[{"path":"sequence.coc1_m2_p3","value":true}],"nominal":"Isolation, assembly, cooling, and wiring chronology recorded.","fault":"Assembly chronology violates a safety prerequisite."},{"id":"close_out","label":"Safety and documentation","requires":[{"path":"setting.work_area_safe","value":true},{"path":"setting.service_report_ready","value":true}],"nominal":"Work-area safety, contingency where required, and service handover recorded.","fault":"Complete safety close-out and the service report before final verification."}],"completion":[{"path":"result.coc1_m2_test_4","value":true}],"operations":[{"id":"close_work_area","label":"Record 5S and 3Rs work-area close-out","effects":{"work_are