('coc1_m3', 'css-sag-20261009-v1', '{"id":"coc1_m3","cocId":"coc1","title":"Install and Configure a Workstation OS","scenario":"Install a workstation OS on a blank GPT drive using UEFI installation media. Configure storage mode, install the network driver, restart, and verify boot and device readiness.","environmentLabel":"Workstation installation bench","practiceGuidance":"Check the firmware and storage specification, select installation media and destination, then verify the driver after restarting.","scene":{"id":"coc1_m3_scene","backgroundAsset":"assets/images/COC1.png","objects":[{"id":"firmware_console","label":"UEFI setup console","x":0.08,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["firmware_console_port"],"initialState":"neutral","metadata":{"schematicRole":"primary","description":"UEFI setup console","replaceableAsset":"assets/simulation/schematics/firmware_console.svg","imageAsset":null}},{"id":"system_disk","label":"GPT system disk","x":0.38,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["system_disk_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"GPT system disk","replaceableAsset":"assets/simulation/schematics/system_disk.svg","imageAsset":null}},{"id":"installation_media","label":"OS installation media","x":0.6799999999999999,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["installation_media_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"OS installation media","replaceableAsset":"assets/simulation/schematics/installation_media.svg","imageAsset":null}},{"id":"driver_media","label":"Device driver media","x":0.08,"y":0.44000000000000006,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["driver_media_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Device driver media","re