('coc1_m5', 'css-sag-20261009-v1', '{"id":"coc1_m5","cocId":"coc1","title":"Install Drivers and Test the System","scenario":"A newly assembled workstation reports an integration fault.","environmentLabel":"Workstation diagnostic bay","practiceGuidance":"Reveal facts progressively and apply a correction only after recording diagnostics.","scene":{"id":"coc1_m5_scene","backgroundAsset":"assets/images/COC1.png","objects":[{"id":"workstation","label":"Workstation","x":0.08,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["workstation_port"],"initialState":"neutral","metadata":{"schematicRole":"primary","description":"Workstation","replaceableAsset":"assets/simulation/schematics/workstation.svg","imageAsset":null}},{"id":"display","label":"Display subsystem","x":0.38,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["display_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Display subsystem","replaceableAsset":"assets/simulation/schematics/display.svg","imageAsset":null}},{"id":"storage","label":"Storage subsystem","x":0.6799999999999999,"y":0.1,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["storage_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Storage subsystem","replaceableAsset":"assets/simulation/schematics/storage.svg","imageAsset":"assets/COC1/Mission 1/ssd.png"}},{"id":"network","label":"Network subsystem","x":0.08,"y":0.44000000000000006,"width":0.24,"height":0.22,"hotspotType":"inspect_and_select","connectionNodeIds":["network_port"],"initialState":"neutral","metadata":{"schematicRole":"supporting","description":"Network subsystem","replaceableAsset":"assets/simulation/schematics/network.svg","imageAsset":null}}],"initialStatus":{"schematic":true,"replaceableAssets":true,"statusLabel":"Awaiting inspection","sceneKind":"maintenanceBay"}},"phases":[{"id":"coc1_m5_p1","title":"Inspect symptom","instruction":"Inspect the reported symptom and visible system state.","primaryInteraction":"troubleshoot","supportingInteractions":[],"availableObjectIds":["workstation","display","storage","network"],"feedbackIds":["coc1_m5_constraint"],"presentation":{"component":"troubleshooting","symptom":"The workstation starts, but the storage subsystem remains unavailable.","diagnostic_actions":[{"id":"inspect_startup_indicators","label":"Inspect startup indicators","reveals_fact_id":"startup_indicator_fact"}],"facts":{"startup_indicator_fact":"The power indicator remains steady while the storage activity LED stays amber after three startup flashes."},"required_fact_ids":["startup_indicator_fact"],"equipment":{"single_connection":true},"mechanics":["inspect_symptom"]}},{"id":"coc1_m5_p2","title":"Choose diagnostic tool","instruction":"Choose a diagnostic action that can reveal a new fact.","primaryInteraction":"troubleshoot","supportingInteractions":[],"availableObjectIds":["workstation","display","storage","network"],"feedbackIds":["coc1_m5_constraint"],"presentation":{"component":"troubleshooting","symptom":"Select a diagnostic action that can distinguish device detection from operating-system access.","diagnostic_actions":[{"id":"open_storage_inventory","label":"Open storage inventory","reveals_fact_id":"storage_inventory_fact","requires":[{"path":"tool.storage","value":"firmware_inventory"}]}],"facts":{"storage_inventory_fact":"The firmware storage inventory lists one device on SATA port 1, and the port status is up."},"required_fact_ids":["storage_inventory_fact"],"equipment":{"single_connection":true,"tools":[{"id":"firmware_inventory","label":"Firmware storage console","compatible_categories":["storage"]},{"id":"display_calibrator","label":"Display calibrator","compatible_categories":["display"]}],"targets":[{"id":"storage","label":"Storage controller","category":"storage"}],"completion":[{"path":"tool.storage","value":"firmware_inventory"}]},"mechanics":["choose_diagnostic_tool"]}},{"id":"coc1_m5_p3","title":"Troubleshoot progressively","instruction":"Record diagnostic facts before unlocking the corrective action.","primaryInteraction":"troubleshoot","supportingInteractions":[],"availableObjectIds":["workstation","display","storage","network"],"feedbackIds":["coc1_m5_constraint"],"presentation":{"component":"troubleshooting","symptom":"The workstation starts, but one subsystem remains unavailable.","diagnostic_actions":[{"id":"inspect_device_status","label":"Inspect device status","reveals_fact_id":"device_status_fact"},{"id":"run_subsystem_probe","label":"Run subsystem probe","reveals_fact_id":"subsystem_probe_fact"},{"id":"inspect_connection_log","label":"Inspect connection log","reveals_fact_id":"connection_log_fact"}],"facts":{"device_status_fact":"Firmware inventory lists the storage device, while the operating system reports it unavailable.","subsystem_probe_fact":"The storage probe returns a 1.8-second timeout with no readable volume.","connection_log_fact":"The connection log records three storage-link resets during startup."},"required_fact_ids":["device_status_fact","subsystem_probe_fact","connection_log_fact"],"equipment":{"single_connection":true},"mechanics":["troubleshoot_progressively"]}},{"id":"coc1_m5_p4","title":"Apply correction","instruction":"Apply the correction supported by the recorded facts.","primaryInteraction":"decide","supportingInteractions":[],"availableObjectIds":["workstation","display","storage","network"],"feedbackIds":["coc1_m5_constraint"],"presentation":{"choices":[{"id":"replace_storage_cable","label":"Isolate power and replace the unstable SATA data cable","equipment_effects":{"storage_link_stable":true}},{"id":"install_display_driver","label":"Reinstall the display driver","equipment_effects":{"storage_link_stable":false}},{"id":"format_storage","label":"Format the storage volume","equipment_effects":{"storage_link_stable":false}}],"component":"scenario_decisio