e controls before changing its configuration.","imageAsset":null},{"id":"network_interface","label":"Network interface","description":"Network interface","inspection":"Network interface is available in the coc4_m3 workspace. Inspect its status using the phase controls before changing its configuration.","imageAsset":null},{"id":"route_monitor","label":"Route monitor","description":"Route monitor","inspection":"No route measurement has been made. Trace the request path before proposing a routing change.","imageAsset":null}]}},{"id":"coc4_m3_p2","title":"Run software diagnostic","instruction":"Choose a software diagnostic to reveal one recorded fact.","primaryInteraction":"troubleshoot","supportingInteractions":[],"availableObjectIds":["workstation","application_log","service_monitor","network_interface","route_monitor"],"feedbackIds":["coc4_m3_constraint"],"presentation":{"diagnostic_actions":[{"id":"inspect_application_log","label":"Inspect application log","reveals_fact_id":"application_log_fact"},{"id":"inspect_adapter_status","label":"Inspect adapter status","reveals_fact_id":"adapter_status_fact"},{"id":"inspect_service_status","label":"Inspect local service status","reveals_fact_id":"local_service_fact"}],"facts":{"application_log_fact":"The application log records three request timeouts at 14:02:18.","adapter_status_fact":"The Ethernet adapter reports link up at 1 Gbps; no local link error is recorded.","local_service_fact":"The local application service is running and listening on its configured port."},"required_fact_ids":["application_log_fact"],"allow_drag":false,"equipment":{"single_connection":true},"mechanics":["run_software_diagnostic"]}},{"id":"coc4_m3_p3","title":"Interpret software result","instruction":"Interpret the earned software facts before opening network diagnostics.","primaryInteraction":"interpret","supportingInteractions":[],"availableObjectIds":["workstation","application_log","service_monitor","network_interface","route_monitor"],"feedb